223→// isOutdated compares current and latest versions using semantic versioning.
224→// Returns true if current < latest.
225→func isOutdated(current, latest string) bool {
226→	// Ensure versions have "v" prefix for semver package
227→	if !strings.HasPrefix(current, "v") {
228→		current = "v" + current
229→	}
230→	if !strings.HasPrefix(latest, "v") {
231→		latest = "v" + latest
232→	}
233→
234→	// Skip notification for prerelease versions (development builds).
235→	// We don't publish prerelease versions, so these are development builds and shouldn't trigger update notifications.
236→	if semver.Prerelease(current) != "" {
237→		return false
238→	}
239→
240→	// semver.Compare returns -1 if current < latest
241→	return semver.Compare(current, latest) < 0
242→}
